create or replace function public.crm_experiment_power(p_baseline numeric,p_mde numeric default 0.20,p_alpha numeric default 0.05,p_power numeric default 0.80) returns jsonb language plpgsql immutable set search_path=public as $$ declare p1 numeric:=greatest(0.0001,least(0.9999,p_baseline)); p2 numeric:=greatest(0.0001,least(0.9999,p_baseline*(1+p_mde))); z_alpha numeric:=1.95996398454005; z_power numeric:=0.841621233572914; n numeric; begin if p_mde<=0 or p_alpha<=0 or p_alpha>=1 or p_power<=0 or p_power>=1 then raise exception 'invalid_power_parameters'; end if; n:=((z_alpha*sqrt(2*((p1+p2)/2)*(1-(p1+p2)/2))+z_power*sqrt(p1*(1-p1)+p2*(1-p2)))^2)/nullif((p2-p1)^2,0); return jsonb_build_object('baseline_conversion',round(p1,6),'target_conversion',round(p2,6),'relative_mde',p_mde,'alpha',p_alpha,'power',p_power,'required_exposures_per_variant',ceil(n)::int,'method','two_proportion_normal_approximation','note','Planning estimate; final inference remains descriptive unless experimental assumptions are satisfied.'); end; $$; revoke all on function public.crm_experiment_power(numeric,numeric,numeric,numeric) from public,anon; grant execute on function public.crm_experiment_power(numeric,numeric,numeric,numeric) to authenticated;
